# --- Where persistent data (state files, per-host folders) actually lives ---
# IMPORTANT: on most "cloud app" / PaaS platforms, redeploying (pushing a
# fresh copy of the code) tears down the old container/filesystem and builds
# a new one from your source. Anything written to plain local disk -- which
# is what happens by default here -- gets wiped along with it, UNLESS it
# lives on a *persistent volume/disk* that the platform explicitly keeps
# across deploys and you've attached to your app.
#
# DATA_DIR defaults to BASE_DIR (old behavior, so nothing breaks if you
# don't set it) -- but that means your data sits inside the same folder
# that gets replaced on every deploy, which is exactly what's wiping it.
#
# Fix: look in your hosting platform's dashboard for something called
# "persistent disk", "volume", "storage", or similar, attach one, note the
# mount path it gives you (e.g. "/data"), and set the environment variable
# DATA_DIR to that path. Everything below (HOSTS_DIR, STATE_FILE, and every
# per-host lottery_state.json under hosts/<HOST_ID>/) will then live there
# instead, and will survive future "replace the whole code" redeploys.
#
# If your platform genuinely has no persistent-storage option at all, plain
# files can never survive a full redeploy there no matter what DATA_DIR is
# set to -- the real fix in that case is moving state into an external
# database instead of local JSON files, which is a bigger change (ask if
# you want that built).
DATA_DIR = os.environ.get("DATA_DIR", BASE_DIR)
HOSTS_DIR = os.path.join(DATA_DIR, "hosts")
STATE_FILE = os.path.join(DATA_DIR, "superadmin_state.json")

os.makedirs(HOSTS_DIR, exist_ok=True)
if DATA_DIR == BASE_DIR:
    print(
        f"⚠️  DATA_DIR is not set -- data is stored inside the app's own code "
        f"folder ({BASE_DIR}), which most cloud platforms replace on every "
        f"redeploy. Set the DATA_DIR environment variable to a persistent "
        f"volume/disk path if your platform offers one, or your saved data "
        f"will keep disappearing on redeploy."
    )
else:
    print(f"📁 Using persistent DATA_DIR: {DATA_DIR}")


# =============================================================================
# Durable storage abstraction (local disk fallback <-> S3-compatible object
# storage)
# =============================================================================
# Different hosting platforms inject Object Storage credentials under
# different env var names when you link a bucket (some use S3_*, some
# AWS_*, some BUCKET_*/ACCESS_KEY/SECRET_KEY with no prefix at all). Rather
# than guessing one exact naming scheme, this scans ALL environment
# variables for names that look like a bucket / access key / secret key /
# endpoint / region, picking the most S3-specific match for each. It prints
# exactly what it found (or didn't) at startup so you can confirm it picked
# up the right ones -- or set S3_BUCKET / S3_ACCESS_KEY_ID /
# S3_SECRET_ACCESS_KEY / S3_ENDPOINT_URL / S3_REGION yourself to override
# auto-detection entirely. If no bucket is found, everything falls back to
# local JSON files under DATA_DIR exactly as before -- fine for local
# testing, but wiped on redeploy on a platform with an ephemeral
# filesystem.


def _find_env(*name_patterns, prefer_prefixes=("S3_", "AWS_", "OBJECT_STORAGE_", "BUCKET_")):
    """Look through os.environ for a var whose name matches any of the
    regexes in name_patterns (case-insensitive). Among matches, prefer ones
    starting with a known storage-related prefix, then shortest name."""
    candidates = []
    for key, value in os.environ.items():
        if not value:
            continue
        for pat in name_patterns:
            if re.search(pat, key, re.IGNORECASE):
                candidates.append(key)
                break
    if not candidates:
        return None, None
    def sort_key(k):
        preferred = next((i for i, p in enumerate(prefer_prefixes) if k.upper().startswith(p)), len(prefer_prefixes))
        return (preferred, len(k))
    best = sorted(set(candidates), key=sort_key)[0]
    return best, os.environ[best]


_bucket_var, S3_BUCKET = _find_env(r"BUCKET")
_access_var, S3_ACCESS_KEY = _find_env(r"ACCESS_KEY")
_secret_var, S3_SECRET_KEY = _find_env(r"SECRET_(ACCESS_)?KEY")
_endpoint_var, S3_ENDPOINT_URL = _find_env(r"ENDPOINT")
_region_var, S3_REGION = _find_env(r"REGION")
S3_REGION = S3_REGION or "us-east-1"
S3_PREFIX = os.environ.get("S3_PREFIX", "").strip("/")

# Explicit S3_* overrides always win over auto-detection.
if os.environ.get("S3_BUCKET"):
    _bucket_var, S3_BUCKET = "S3_BUCKET", os.environ["S3_BUCKET"]
if os.environ.get("S3_ACCESS_KEY_ID"):
    _access_var, S3_ACCESS_KEY = "S3_ACCESS_KEY_ID", os.environ["S3_ACCESS_KEY_ID"]
if os.environ.get("S3_SECRET_ACCESS_KEY"):
    _secret_var, S3_SECRET_KEY = "S3_SECRET_ACCESS_KEY", os.environ["S3_SECRET_ACCESS_KEY"]
if os.environ.get("S3_ENDPOINT_URL"):
    _endpoint_var, S3_ENDPOINT_URL = "S3_ENDPOINT_URL", os.environ["S3_ENDPOINT_URL"]
if os.environ.get("S3_REGION"):
    _region_var, S3_REGION = "S3_REGION", os.environ["S3_REGION"]

_boto3_client = None
if S3_BUCKET:
    print(
        f"☁️  Object storage env vars detected -- bucket: {_bucket_var}, "
        f"access key: {_access_var or '(none found)'}, "
        f"secret key: {'<found: ' + _secret_var + '>' if _secret_var else '(none found)'}, "
        f"endpoint: {_endpoint_var or '(none -- using AWS default)'}, "
        f"region: {_region_var or '(default us-east-1)'}"
    )
    try:
        import boto3
        client_kwargs = {"region_name": S3_REGION, "endpoint_url": S3_ENDPOINT_URL or None}
        # Only pass explicit keys if we actually found them -- otherwise let
        # boto3 fall back to its own default credential chain (which also
        # picks up standard AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY).
        if S3_ACCESS_KEY and S3_SECRET_KEY:
            client_kwargs["aws_access_key_id"] = S3_ACCESS_KEY
            client_kwargs["aws_secret_access_key"] = S3_SECRET_KEY
        _boto3_client = boto3.client("s3", **client_kwargs)
        # Fail fast and loud at startup if the bucket/credentials don't
        # actually work, instead of silently losing data on first write.
        _boto3_client.head_bucket(Bucket=S3_BUCKET)
        print(f"☁️  Connected to durable object storage: bucket={S3_BUCKET!r}")
    except ModuleNotFoundError:
        print(
            "⚠️  A storage bucket was detected but 'boto3' is not installed "
            "(pip install boto3) -- falling back to local disk storage, "
            "which will NOT survive a redeploy."
        )
        _boto3_client = None
    except Exception as e:
        print(
            f"⚠️  Found bucket {S3_BUCKET!r} but couldn't connect ({e}) -- "
            f"falling back to local disk storage, which will NOT survive a "
            f"redeploy. Double check the detected env vars above are "
            f"actually the linked-bucket credentials."
        )
        _boto3_client = None
else:
    print(
        "⚠️  No object-storage bucket env var detected -- data is stored on "
        "local disk, which most cloud platforms wipe on redeploy. If you've "
        "linked a bucket under Storage, its env vars should already be "
        "injected; if this message still shows, set S3_BUCKET (and "
        "S3_ACCESS_KEY_ID / S3_SECRET_ACCESS_KEY / S3_ENDPOINT_URL if "
        "needed) yourself to point at it explicitly."
    )


class PersistentStore:
    """Reads/writes JSON blobs either to S3-compatible object storage (when
    configured above) or to local disk under DATA_DIR (fallback). `prefix`
    is prepended to every key -- e.g. "hosts/H001" for one host's own state
    -- so each host's data lives at its own S3 key / local path and nothing
    collides with another host or with the super admin's own state."""

    def __init__(self, prefix: str = ""):
        self.prefix = prefix.strip("/")

    def _s3_key(self, key: str) -> str:
        parts = [p for p in (S3_PREFIX, self.prefix, key) if p]
        return "/".join(parts)

    def _local_path(self, key: str) -> str:
        path = os.path.join(DATA_DIR, self.prefix, key) if self.prefix else os.path.join(DATA_DIR, key)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        return path

    def write_json(self, key: str, data) -> None:
        payload = json.dumps(data, ensure_ascii=False, indent=2)
        if _boto3_client is not None:
            _boto3_client.put_object(
                Bucket=S3_BUCKET, Key=self._s3_key(key),
                Body=payload.encode("utf-8"), ContentType="application/json",
            )
            return
        path = self._local_path(key)
        tmp_path = path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write(payload)
        os.replace(tmp_path, path)

    def read_json(self, key: str, default=None):
        if _boto3_client is not None:
            try:
                obj = _boto3_client.get_object(Bucket=S3_BUCKET, Key=self._s3_key(key))
                return json.loads(obj["Body"].read().decode("utf-8"))
            except Exception as e:
                # NoSuchKey (missing object) is expected on first run; any
                # other error just falls back to "no saved state" rather
                # than crashing startup.
                if "NoSuchKey" not in str(e) and "404" not in str(e):
                    log.error(f"S3 read_json({key!r}) error: {e}")
                return default
        path = self._local_path(key)
        if not os.path.exists(path):
            return default
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)


STORE = PersistentStore()  # super admin's own state (superadmin_state.json)


